// Ported from ReUI (MIT, (c) 2025 Keenthemes Inc.) — https://github.com/keenthemes/reui/blob/main/registry/bases/radix/ui/marker.tsx

import { cn } from "@/lib/utils"

import { Slot } from "@radix-ui/react-slot"
import { cva } from "class-variance-authority"
import { type HTMLAttributes } from "react"

const markerVariants = cva(
  "group/marker relative flex min-h-4 w-full items-center gap-2 text-left text-sm text-muted-foreground [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "",
        separator: "before:mr-1 before:h-px before:min-w-0 before:flex-1 before:bg-border after:ml-1 after:h-px after:min-w-0 after:flex-1 after:bg-border",
        border: "border-b border-border pb-2",
      },
    },
    defaultVariants: { variant: "default" },
  },
)

export interface MarkerProps extends HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "separator" | "border"
  asChild?: boolean
}

export function Marker({ className, variant = "default", asChild = false, ...props }: MarkerProps) {
  const Comp = asChild ? Slot : "div"
  return (
    <Comp className={cn(markerVariants({ variant }), className)} data-slot="marker" data-variant={variant} {...props} />
  )
}

export function MarkerIcon({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
  return <span aria-hidden="true" className={cn("size-4 shrink-0", className)} data-slot="marker-icon" {...props} />
}

export function MarkerContent({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      className={cn("min-w-0 wrap-break-word group-data-[variant=separator]/marker:flex-none group-data-[variant=separator]/marker:text-center", className)}
      data-slot="marker-content"
      {...props}
    />
  )
}
